# logo.py: new bouncy KidCog logo (Owl as the "o", a star dotting the "i") in the top bar and on the home page.
import base64, hashlib, os, sys
EXPECT = {'app/src/components/AppMenu.tsx': 'bfc0216cb4893aea1341a70deb05365a', 'app/src/screens/WelcomeScreen.tsx': '77d01dd7268f4113497e23c34dea4226'}
for p, m in EXPECT.items():
    got = hashlib.md5(open(p, 'rb').read()).hexdigest()
    if got != m: sys.exit(f'{p} changed since staging ({got}); not applying')
if os.path.exists('app/src/components/Logo.tsx'): sys.exit('app/src/components/Logo.tsx already exists; not applying')
PAYLOAD = {'app/src/components/Logo.tsx': '', 'app/src/components/AppMenu.tsx': '', 'app/src/screens/WelcomeScreen.tsx': ''}
WANT = {'app/src/components/Logo.tsx': '0e9ff6c6650ef28d148f36dca7a1b86f', 'app/src/components/AppMenu.tsx': '173c3d5c0b85a38859dff1a9d03ff260', 'app/src/screens/WelcomeScreen.tsx': 'ed1f885b57d66e61275d3d67de465561'}
for p, b in PAYLOAD.items():
    open(p, 'wb').write(base64.b64decode(b))
    assert hashlib.md5(open(p, 'rb').read()).hexdigest() == WANT[p], p
    print('wrote', p, WANT[p])
